def table(headers,rs):return '| '+' | '.join(headers)+' |\n|'+ '|'.join('---' for _ in headers)+'|\n'+''.join('| '+' | '.join(str(c) for c in row)+' |\n' for row in rs)
def run():
 c=readj('manifest/coverage.json');stats=readj('reports/corpus_statistics.json');dedup=readj('reports/deduplication.json');sv=readj('reports/symbol_validation.json');sources=rows('manifest/sources.jsonl');decisions=rows('manifest/source_decisions.jsonl')+rows('manifest/ecosystem_decisions.jsonl')+rows('manifest/inside_decisions.jsonl');assemblies=rows('manifest/assemblies.jsonl');token=readj('manifest/tokenizer.json');tests=(ROOT/'reports/tests.log').read_text();rebuild=readj('reports/rebuild_verification.json')
 full_records=rows('corpus/full.records.jsonl');derived_records=rows('corpus/derived.records.jsonl')
 token_hashes={r['id']:r['text_sha256'] for r in rows('manifest/record_tokens.jsonl')}
 assert all(token_hashes.get(r['id'])==digest(r['text'].encode()) for r in full_records),'Token statistics are stale for current text'
 assert stats['total']['records']==len(full_records),'Token statistics do not match the current export'
 assert stats['by_corpus'].get('derived',{}).get('records',0)==len(derived_records),'Derived token statistics are stale'
 familyrows=[]
 for f,v in c['levels']['family'].items():familyrows.append([f,v['discovered'],v['documented'],v['represented'],v['missing_documentation'],v['absent']])
 write('reports/coverage.md','# Corpus/API coverage\n\nTarget: **Rhino 8 SR35 8.35.26251.13002 (macOS)**. Native SDK/openNURBS: **8.35.26251.13001 (Windows SDK release)**.\n\n'+table(['Family','Discovered','Semantic documentation matched','Represented','No matched semantic documentation','Absent'],familyrows)+'\n**These percentages apply to the inventoried surfaces, not to every independent McNeel product.** .NET inventory includes public/protected members and shipped reference-assembly additions. C++ inventory comes from distributed headers using Doxygen; full comments/source remain intact even where Doxygen does not recognize their prose as documentation. Thus the documentation count is deliberately conservative.\n\n'+table(['Metric','Value'],c['total'].items())+'\n'+table(['Source processing','Count'],c.get('source_processing',{}).items())+'\nGrasshopper documentation is verified in the corresponding API record text; XML presence alone is not counted as semantic richness. See `reports/documentation_richness.md` and its per-symbol attachment manifest.\n\nDetailed assembly, namespace, type and member-kind coverage: `manifest/coverage.json`. Every individual symbol is in the symbol manifests; exceptions, including signature-only records, are enumerated in `manifest/coverage_exceptions.jsonl`. Overloads have distinct XML documentation IDs and signatures. C++ enums have separate value entries.\n\nMetadata/XML extraction failures: **'+str(c['parsing_failures'])+'**. Source decisions: '+json.dumps(c['source_decisions'],sort_keys=True)+'.\n\nSee `reports/source_inventory.md` for additional-family scope gaps. No namespace has been dropped because of perceived usefulness.\n')
 lengths=stats['total'];rowsstats=[]
 for f,v in stats['by_family'].items():rowsstats.append([f,v['records'],f"{v['tokens']:,}",f"{v['proportion']:.2%}",v['median'],v['p95'],v['max']])
 write('reports/corpus_statistics.md','# Exact Qwen tokenization\n\nTokenizer: **Qwen/Qwen3.8-27B**, commit `'+token['upstream_commit']+'`; tokenizers '+token['tokenizers_version']+'. Both tokenizer JSON files match the local `gcoli/Qwen3.8-27B-oQ6e-mtp` byte-for-byte. Model weights were not loaded.\n\nCounts apply to raw record text with **no chat template, added special tokens, padding, truncation or packing**. Record boundaries are separate from any future training sequence length.\n\n'+table(['Family','Records','Tokens','Proportion','Median','p95','Maximum'],rowsstats)+'\n'+table(['Representation','Records','Tokens'],[[k,v['records'],f"{v['tokens']:,}"] for k,v in stats['by_corpus'].items()]+[['Total',lengths['records'],f"{lengths['tokens']:,}"]])+'\n'+table(['Length statistic','Tokens'],[[k,lengths[k]] for k in ['mean','median','p90','p95','p99','max']])+'\n'+table(['Length bin (tokens)','Records'],lengths['histogram'].items())+'\nPer-record counts: `manifest/record_tokens.jsonl`. Machine-readable family distributions: `reports/corpus_statistics.json`.\n')
 write('reports/deduplication.md','# Deduplication\n\n'+table(['Metric','Value'],[[k,v] for k,v in dedup.items() if not isinstance(v,(list,dict))])+'\nOnly exact text matches with identical API family, language and version are collapsed; provenance and symbol associations are merged. Near analysis uses whitespace/case-normalized document equality and makes **no deletions**. This is a conservative near-duplicate analysis, not semantic similarity detection.\n\nRepeated API explanations, overloads, accessor descriptions and language variants remain. Exact raw-source duplicates share a SHA-256 cache object. Removing the embedded PNG asset is source classification, not deduplication. All semantic code segments reconstruct the complete original source exactly.\n')
 failures=rows('manifest/parsing_failures.jsonl')+rows('manifest/source_parsing_failures.jsonl')+rows('manifest/cpp_parsing_failures.jsonl')+rows('manifest/metadata_failures.jsonl')+rows('manifest/ecosystem_parsing_failures.jsonl')+rows('manifest/inside_parsing_failures.jsonl')
 py=Counter(r['status'] for r in rows('manifest/python_validation.jsonl'));cs=Counter(r['status'] for r in rows('manifest/csharp_validation.jsonl'));compile_results=rows('manifest/compilation_results.jsonl')
 write('reports/parsing_failures.md','# Parsing and example validation\n\nFinal metadata/XML/normalization parser failures: **'+str(len(failures))+'**. Native legacy-encoded comments are losslessly transcoded for Doxygen; original bytes and encoding remain cached.\n\nPython syntax checks: '+json.dumps(dict(py))+'. Failures include valid Python 2 syntax, deliberately failing teaching examples and real source defects; they are not all bad Rhino API usage. The installed Python 3 `AnnotateCurveForm.py` has unexpected indentation at line 122. Its exact source and explicit exception are retained.\n\nIronPython2 syntax compilation: '+json.dumps(dict(Counter(r['status'] for r in rows('manifest/python2_validation.jsonl'))))+'. Code was compiled for syntax, never executed. Three source files fail both Python grammars: ex_addnurbscircle.py and the py27/py39 copies of AnnotateCurveForm.py.\n\nC# syntax checks (Roslyn 4.14): '+json.dumps(dict(cs))+'. The two regular-C# parse failures are a ScriptEditor library with `#r` and a partial Compute generator header template that is excluded from canonical text; these require their respective preprocessing contexts. Four complete unmodified official C# examples compiled against target RhinoCommon/.NET8 metadata. Both full Compute C# clients also compiled against Rhino3dm 8.35/.NET8 metadata; 970 of 972 remote endpoint strings match target member names (the remaining two are the same Python-evaluation server helper). Overload encodings are not fully bound. Clang successfully syntax-checked the public openNURBS umbrella header. Native Windows plug-in examples were not compiled on macOS; no Windows toolchain is installed. No examples were executed in Rhino or external Windows hosts. Host source preprocessing/declaration validation uses Roslyn 4.14 and declared Rhino8/Revit or AutoCAD framework configurations; source changes for inactive branches are logged.\n\nStatic dotted-reference candidates: **'+str(sv['dotted_text_candidates_requiring_binding'])+'**. These include VBScript `Rhino.*` calls, filenames, generic spellings, chained properties, external Compute/rhino3dm APIs and actual stale references. They are enumerated in `manifest/reference_exceptions.jsonl`; the analysis is **not full typed binding**. XML cref exceptions: **'+str(sv['xml_reference_exceptions'])+'**, separately enumerated. Invalid declared record symbols/provenance: **'+str(sv['invalid_record_symbols_or_provenance'])+'**.\n')
 if (ROOT/'reports/guide_code_validation.json').exists():
  gc=readj('reports/guide_code_validation.json')
  block_report='\n## Python guide-code blocks\n\n'+str(gc['blocks'])+' explicitly labelled Python blocks were syntax-checked without execution: '+str(gc['python3_passed'])+' parse as Python3, '+str(gc['python2_passed'])+' as Python2, and '+str(gc['both_grammars_failed'])+' fail both standalone grammar checks. These include incomplete teaching snippets, shell commands labelled Python, indentation fragments and genuine publisher defects. The Rhino.Inside.Revit getting-started example contains the invalid original line `import RhinoInside API`. Original source remains unchanged. Exact record/block IDs, source provenance, code hashes and both diagnostics are in `manifest/guide_code_validation.jsonl`.\n'
  write('reports/parsing_failures.md',(ROOT/'reports/parsing_failures.md').read_text()+block_report)
 rawdocs=len({p for r in rows('corpus/canonical.records.jsonl') for p in r['provenance']});paths=['corpus/canonical.records.jsonl','corpus/derived.records.jsonl','corpus/full.records.jsonl','corpus/training_text.jsonl']
 artifacts={p:{'sha256':digest((ROOT/p).read_bytes()),'bytes':(ROOT/p).stat().st_size} for p in paths};jsonwrite('manifest/artifacts.json',artifacts)
 conflicts=rows('manifest/version_conflicts.jsonl');future_count=len({(r['assembly'],r['doc_id']) for r in rows('manifest/future_documentation_notes.jsonl')})
 unresolved=[
 {'id':'version_annotation_conflicts','severity':'publisher_metadata_discrepancy','reason':str(future_count)+' distinct members in RhinoCommon/Rhino3dm XML are annotated since Rhino 8.36/9.0 despite existing in the selected 8.35 binaries. Including accessor and declaring-type propagation, '+str(len(conflicts))+' symbol documentation blocks retain exact-release XML and original notes, with an explicit availability-discrepancy notice. Inclusion is resolved by brief section 4: selected binary presence is authoritative for existence. The publisher annotation itself remains unresolved. See manifest/version_conflicts.jsonl.'},
 {'id':'git_checkpoint','severity':'blocking_project_requirement','reason':'Workspace policy denies creation/writes under .git. git init failed with Operation not permitted; scripts/manifests/reports exist but are not version-controlled commits.'},
 {'id':'ecosystem_scope','severity':'explicit_version_exclusions','reason':'Stable Rhino.Inside.Revit 1.35 and CPython 0.8.2 are inventoried and included as separate families; AutoCAD/Civil3D 1.3.5 source declarations are inventoried separately and excluded because its README explicitly labels the project early Alpha testing; exact SR35 RhinoWindows metadata is included. The independently inventoried Rhino.Inside loader 8.0.7-beta and Rhino.Testing 8.0.28-beta are excluded under the no-unapproved-beta rule. Historical RhinoMobile (last repository push 2018) and current Rhino9-only native SDK repository are excluded with cached evidence. Windows COM binary comparison and host runtime/typed binding remain limitations.'},
 {'id':'example_binding','severity':'validation_limit','reason':str(sv['dotted_text_candidates_requiring_binding'])+' dotted-reference candidates and '+str(sv['xml_reference_exceptions'])+' XML references have explicit exceptions, not full typed validation. Known source defects are retained with provenance; representative compiles do not validate every example. Separate Python guide-block checks and their explicit original-source defects are recorded in reports/parsing_failures.md and manifest/guide_code_validation.jsonl.'},
 {'id':'documentation_gaps','severity':'coverage_disclosure','reason':str(c['total']['symbols_discovered']-c['total']['symbols_documented'])+' inventoried declarations lack matched semantic XML/docstrings. Every declaration is represented by metadata or full header/source. Rhino.UI.dll has no separate XML in the installed distribution or matching RhinoCommon/RhinoWindows packages, and no exact type matches in the inspected web API dataset. Selected official guides/examples remain included. See reports/documentation_richness.md for the exact search and attachment evidence.'},
 {'id':'native_parser','severity':'validation_limit','reason':'Doxygen plus full-header preservation and Clang umbrella-header check establish a reproducible native inventory; explicit Windows/macOS/Linux-openNURBS macro profiles are inventoried, with zero generic-only declarations after source-coordinate reconciliation; these have not been independently exhaustively compared to a Windows compiler AST.'},
 {'id':'redistribution','severity':'later_review','reason':'Per-source license/copyright evidence retained; redistribution rights for corpus or eventual trained model have not been approved.'}]
 if readj('STATE.json').get('git_checkpointing',{}).get('status')=='available':
  unresolved=[x for x in unresolved if x['id']!='git_checkpoint']
 jsonwrite('manifest/unresolved_issues.json',unresolved)
 report='# Corpus-preparation report\n\n**Status: '+('corpus artifacts complete and ready for review; see STATE.json for Git capability status' if readj('STATE.json').get('corpus_build_complete') else 'validation in progress; canonical completion not yet certified')+'. No training has started.**\n\n'
 report+='## Included\n\nTarget **Rhino 8 SR35, macOS build 8.35.26251.13002**; matching native SDK and openNURBS **8.35.26251.13001**. Includes public/protected installed .NET APIs, overloads, attributes/defaults, installed/matching XML, Rhino scripting source, official conceptual guides and samples, native/public openNURBS headers and implementation examples, Eto UI, and discovered first-party SDK support assemblies. No namespace whitelist is used.\n\n'
 report+=f"{len(sources):,} source/evidence entries are cached; **{rawdocs:,} distinct source files/binaries directly support canonical records**. Every repository file has a disposition. All 322 current RhinoCommon website example filenames map to the pinned Rhino8 samples repository. See the source inventory for exact inclusions/exclusions and the manifests for hashes and provenance.\n\n"
 report+=table(['Source processing','Count'],c.get('source_processing',{}).items())+'\n'
 report+=table(['Metric','Result'],[['Inventoried symbols',f"{c['total']['symbols_discovered']:,}"],['Represented symbols',f"{c['total']['symbols_represented']:,}"],['Absent inventoried symbols',c['total']['symbols_absent']],['Matched semantic documentation',f"{c['total']['symbols_documented']:,}"],['Canonical records',stats['by_corpus']['canonical']['records']],['Canonical tokens',f"{stats['by_corpus']['canonical']['tokens']:,}"],['Derived records',stats['by_corpus'].get('derived',{}).get('records',0)],['Derived tokens',f"{stats['by_corpus'].get('derived',{}).get('tokens',0):,}"],['Total tokens',f"{stats['total']['tokens']:,}"],['Final parsing failures',len(failures)],['Automated suite',re.search(r'Ran (\d+) tests',tests)[1]+' tests passed' if re.search(r'Ran \d+ tests.*\n\nOK',tests,re.S) else 'see tests.log'],['Cached canonical rebuild byte-identical',rebuild['byte_identical']]])
 report+='\nAccepted derived records are deterministic, canonical-source-linked type inheritance/interface relationships, generated only after the canonical completion checkpoint. Assembly identity is used to distinguish identical type names across RhinoCommon and Rhino3dm. Early trial output remains outside production under derived/connective/candidates.records.jsonl. No generated code or mixing weight was introduced.\n\n## Omissions and unresolved issues\n\n'+''.join('- **'+x['id']+'** — '+x['reason']+'\n' for x in unresolved)
 report+='\nCoverage is 100% of the inventoried target surfaces, reported separately from semantic documentation richness. Included stable host integrations and excluded alpha/beta integrations now have explicit inventory denominators; no current host family is silently deferred. Beta and historical exclusions are version-based, not convenience-based. Host AST coverage is not a claim of runtime or full typed binding.\n\n## Version, duplication and record lengths\n\nThe numeric version audit detected '+str(future_count)+' distinct future-annotated members in selected release XML; '+str(len(conflicts))+' affected symbol documentation blocks (including accessors/type propagation) preserve the exact-release XML and conflicting notes with explicit discrepancy notices. All 94 original annotated members physically exist in the selected 8.35 binaries; source-priority rule 4 resolves their inclusion without admitting a future-only symbol. No Rhino9/GH2 binary/reference set is included in production. AutoCAD/Civil3D source is retained outside production because the publisher labels it alpha. Newer-only guides and sections are excluded. Apart from the explicitly labelled numeric since-version discrepancies, the remaining Rhino9 text-marker hits are reviewed compatibility/maintenance comments, a hypothetical licensing example, a Rhino8 Hops comment naming the internal repository that supplied a UI pattern, or a numbered illustration filename, not added future API records. Every remaining marker context has a SHA-locked review in config/version_context_reviews.json. Live Grasshopper and C++ references identify Rhino9 and remain discovery evidence only. Current RhinoCommon JSON is a single mixed-version dataset; target installed XML has priority.\n\n'
 report+=f"Exact duplicate records removed: **{dedup['exact_records_removed']}**; exact token reduction: **{dedup.get('exact_tokens_removed',0)}**. Near-duplicate removals: **0**. Semantic repetition was retained. Lengths: median **{lengths['median']}**, p90 **{lengths['p90']}**, p95 **{lengths['p95']}**, p99 **{lengths['p99']}**, maximum **{lengths['max']}** tokens. Large code documents are segmented at declaration/member or encoding-map boundaries, with tested exact reassembly.\n\n"
 report+='## Artifacts and reproducibility\n\n'+''.join('- `'+p+'` — SHA-256 `'+v['sha256']+'`\n' for p,v in artifacts.items())+'\n`README.md` and `scripts/rebuild_all.sh` describe offline restoration/rebuild. Cached canonical rebuilding was tested in fresh processes without conversation context. Dependencies, pinned downloads, raw hashes, exceptions and tokenizer compatibility are on disk. No train/validation split, sequence packing, optimizer settings or model training were created.\n\n## Next step\n\nReview the documented publisher annotation discrepancies, explicit version exclusions, documentation richness and validation limitations. After corpus approval, a separate experiment can define reproducible temporary validation splits and a closed-book evaluation recipe. This report does not select training architecture, hyperparameters or mixture weights.\n'
